insert into ponew values
(1, 1, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'An inhaled peanut in a child is removed by:', '["Rigid bronchoscopy under general anaesthesia", "Making the child vomit", "Chest physiotherapy alone", "Oral antibiotics and chest physiotherapy at home"]'::jsonb, 0, 'Peanuts swell and cause chemical irritation.', 'PON 423 · Paediatric Surgery'),
(1, 2, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Before paediatric surgery, the nurse weighs the child mainly to:', '["Decide the theatre list order", "Calculate drug doses and fluids accurately", "Check for obesity only, as weight does not affect doses", "Record growth for school"]'::jsonb, 1, 'Weight in kilograms must be recorded.', 'PON 423 · Paediatric Surgery'),
(1, 3, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A child''s short trachea means that an endotracheal tube can easily:', '["Move into a main bronchus with head flexion", "Never move, as children''s tubes are always cuffed", "Fall out with head extension only", "Enter the oesophagus on its own"]'::jsonb, 0, 'Secure the tube well and check after each move.', 'PON 423 · Paediatric Surgery'),
(1, 4, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'After cleft palate repair, the child is fed with:', '["A cup or spoon as advised, avoiding hard objects in the mouth", "Hard biscuits and a firm teat to strengthen the palate", "Nothing for two weeks", "A hard teat and straw"]'::jsonb, 0, 'Protect the suture line.', 'PON 423 · Paediatric Surgery'),
(1, 5, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Biliary atresia should be treated by the Kasai procedure ideally before:', '["10 years of age", "Puberty", "2 years of age", "60 days of age"]'::jsonb, 3, 'Persistent jaundice beyond 2 weeks with pale stools must be investigated.', 'PON 423 · Paediatric Surgery'),
(1, 6, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Paraphimosis is an emergency because:', '["It causes infertility immediately", "The retracted foreskin constricts the glans and blood flow", "It causes deafness and hearing loss if not treated", "It is a type of cancer"]'::jsonb, 1, 'Reduce it urgently, sometimes under anaesthesia.', 'PON 423 · Paediatric Surgery'),
(1, 7, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Before surgery for Wilms'' tumour, the abdomen should NOT be:', '["Measured or examined gently by the surgeon", "Inspected", "Documented", "Palpated repeatedly"]'::jsonb, 3, 'Rough handling may rupture the tumour and spread it.', 'PON 423 · Paediatric Surgery'),
(1, 8, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Bladder exstrophy is a congenital condition in which:', '["The kidneys are fused", "The urethra opens on the back of the penis only", "The bladder is open and exposed on the lower abdomen", "The bladder is completely absent from birth"]'::jsonb, 2, 'Keep the bladder covered with cling film and moist.', 'PON 423 · Paediatric Surgery'),
(1, 9, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Post-operative pain in toddlers is best assessed using:', '["Checking pupil size and blood pressure only", "A behavioural tool such as FLACC", "Asking them to rate pain 0–10", "Measuring blood glucose"]'::jsonb, 1, 'Older children can use faces scales.', 'PON 423 · Paediatric Surgery'),
(1, 10, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'After circumcision in a child, the parents are taught to:', '["Bathe the area in alcohol", "Remove the dressing by force", "Watch for bleeding and apply petroleum jelly to prevent sticking", "Avoid passing urine for 24 hours so the wound heals"]'::jsonb, 2, 'Seek help if urine is not passed within 12 hours.', 'PON 423 · Paediatric Surgery'),
(1, 11, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'In children, inhaled foreign bodies most often lodge in the:', '["Right main bronchus", "Nasopharynx", "Left main bronchus", "Oesophagus behind the larynx"]'::jsonb, 0, 'The right bronchus is wider and more vertical.', 'PON 423 · Paediatric Surgery'),
(1, 12, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'The recommended maintenance fluid for the first 10 kg of body weight (Holliday-Segar) is:', '["4 mL/kg/hour", "1 mL/kg/hour", "0.5 mL/kg/hour", "10 mL/kg/hour"]'::jsonb, 0, 'Next 10 kg: 2 mL/kg/h; each kg above 20: 1 mL/kg/h.', 'PON 423 · Paediatric Surgery'),
(1, 13, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Children lose heat quickly during surgery mainly because they have:', '["More body fat than adults", "Higher blood pressure", "A slower metabolism and more body fat than adults", "A large surface area relative to body weight"]'::jsonb, 3, 'Use warm theatres, radiant heaters and warm fluids.', 'PON 423 · Paediatric Surgery'),
(1, 14, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Most umbilical hernias in infants:', '["Strangulate in the first week", "Close on their own by about 4–5 years", "Need emergency surgery", "Turn cancerous if they are not removed early"]'::jsonb, 1, 'Surgery is offered if they persist or are large.', 'PON 423 · Paediatric Surgery'),
(1, 15, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Hypertrophic pyloric stenosis typically causes which blood picture?', '["Normal electrolytes always", "Metabolic acidosis with high potassium", "Hypochloraemic, hypokalaemic metabolic alkalosis", "Respiratory acidosis with a low bicarbonate level"]'::jsonb, 2, 'Correct before surgery.', 'PON 423 · Paediatric Surgery'),
(1, 16, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Incarcerated inguinal hernia in paediatrics is treated by', '["Emergency surgery", "Anti-inflammatory", "Antibiotics", "Analgesics"]'::jsonb, 0, 'An incarcerated hernia is a surgical emergency requiring urgent operative repair.', 'PON 423 · Paediatric Surgery'),
(1, 17, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Circumcision should NOT be performed in a baby with hypospadias because:', '["It causes a hydrocele and urinary tract infection", "It increases bleeding in all babies", "The foreskin may be needed for the repair", "It cures hypospadias"]'::jsonb, 2, 'Refer to a paediatric urologist.', 'PON 423 · Paediatric Surgery'),
(1, 18, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'The narrowest part of the airway in young children (traditionally) is the:', '["Nasopharynx", "Cricoid ring", "Carina", "Vocal cords in all ages"]'::jsonb, 1, 'This is why uncuffed tubes were used traditionally.', 'PON 423 · Paediatric Surgery'),
(1, 19, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Hirschsprung''s disease is confirmed by:', '["Chest X-ray", "Blood culture", "A urine test and an abdominal ultrasound scan", "Rectal biopsy showing absence of ganglion cells"]'::jsonb, 3, 'Treatment is a pull-through operation.', 'PON 423 · Paediatric Surgery'),
(1, 20, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A congenital hydrocele in an infant usually:', '["Means a testicular tumour", "Needs immediate drainage", "Resolves by about 1–2 years of age", "Causes kidney failure if not drained at once"]'::jsonb, 2, 'Surgery is done if it persists or a hernia is present.', 'PON 423 · Paediatric Surgery'),
(1, 21, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'Kidney function is best monitored after major urological surgery by:', '["Peak expiratory flow and chest expansion", "Pupil size", "Hair colour", "Urine output, serum creatinine and electrolytes"]'::jsonb, 3, 'Rising creatinine suggests kidney injury.', 'PON 423 · Urology'),
(1, 22, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A kidney transplant is usually placed in the:', '["Chest", "Upper abdomen near the stomach", "Iliac fossa", "Original kidney position in the back"]'::jsonb, 2, 'The vessels are joined to the iliac artery and vein.', 'PON 423 · Urology'),
(1, 23, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'After a vasectomy, the man is told that:', '["He is sterile immediately and no other contraception is ever needed", "The operation is easily reversed", "He cannot have sex for a year", "Contraception must continue until semen tests confirm no sperm"]'::jsonb, 3, 'Sperm remain in the tubes for some weeks.', 'PON 423 · Urology'),
(1, 24, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'The ''prehn sign'' (pain relieved by lifting the testis) is more suggestive of:', '["Hydrocele with fluid around the testis", "Varicocele", "Epididymitis than testicular torsion", "Testicular torsion"]'::jsonb, 2, 'It is not reliable enough to exclude torsion.', 'PON 423 · Urology'),
(1, 25, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A patient with renal colic typically:', '["Has no pain until the stone reaches the bladder", "Has pain only on eating", "Lies very still", "Moves about and cannot find a comfortable position"]'::jsonb, 3, 'Peritonitis makes patients lie still.', 'PON 423 · Urology'),
(1, 26, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A man with sickle cell disease and priapism should first receive:', '["Analgesia, hydration and urgent urology review", "Ice packs only for 24 hours", "Oral iron tablets and ice packs at home", "No treatment"]'::jsonb, 0, 'Delay can cause permanent erectile dysfunction.', 'PON 423 · Urology'),
(1, 27, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A urine sample for culture from a catheter should be taken:', '["From the drainage bag tap after it has been emptied", "From the drainage bag", "From the sampling port using aseptic technique", "By disconnecting the bag"]'::jsonb, 2, 'Bag urine is contaminated.', 'PON 423 · Urology'),
(1, 28, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A varicocele is:', '["An undescended testis", "Dilated veins around the testis, usually on the left", "A twisted testis needing surgery within 6 hours", "Fluid around the testis"]'::jsonb, 1, 'It feels like a ''bag of worms'' and may affect fertility.', 'PON 423 · Urology'),
(1, 29, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'Common symptoms with a ureteric stent in place include:', '["Facial weakness", "Hearing loss", "Frequency, urgency, mild blood in urine and loin pain on voiding", "Visual loss and ringing in the ears from the stent material"]'::jsonb, 2, 'Fever or severe pain should be reported.', 'PON 423 · Urology'),
(1, 30, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'Haematuria with clots after a renal biopsy should be:', '["Treated by restricting fluids", "Ignored as normal, as the patient will pass clots for a week", "Treated with heat packs", "Reported, with close monitoring of pulse, BP and Hb"]'::jsonb, 3, 'Bed rest is usual for several hours after biopsy.', 'PON 423 · Urology'),
(1, 31, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A nephrostomy tube drains urine:', '["From the pleural space", "From the stomach to a bag on the abdomen", "From the bladder through the urethra", "Directly from the kidney through the skin"]'::jsonb, 3, 'Secure the tube well and record output.', 'PON 423 · Urology'),
(1, 32, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'Before ESWL (shock wave lithotripsy), it is important to check that the patient:', '["Is on warfarin with an INR above 4", "Is not pregnant and has no bleeding disorder", "Has a full bladder", "Has eaten a heavy meal"]'::jsonb, 1, 'Haematuria is common after treatment.', 'PON 423 · Urology'),
(1, 33, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'Superficial bladder cancer is usually treated first by:', '["Circumcision and urethral dilatation", "Transurethral resection of bladder tumour (TURBT)", "Radical nephrectomy", "Prostatectomy"]'::jsonb, 1, 'Intravesical BCG or chemotherapy may follow.', 'PON 423 · Urology'),
(1, 34, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'After hypospadias repair, the main nursing priority is:', '["Bathing in hot water immediately", "Encouraging the child to remove the catheter", "Protecting the urinary stent or catheter and the dressing", "Restricting all fluids to reduce urine output on the wound"]'::jsonb, 2, 'Keep the dressing clean and dry.', 'PON 423 · Urology'),
(1, 35, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A percutaneous nephrolithotomy patient develops breathlessness after surgery. The nurse should suspect:', '["Constipation from the opioid analgesia given after surgery", "Pleural injury such as pneumothorax or hydrothorax", "Normal recovery", "Urinary tract infection"]'::jsonb, 1, 'Upper pole access can injure the pleura.', 'PON 423 · Urology'),
(1, 36, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'Most renal injuries after blunt trauma in stable patients are managed:', '["With immediate nephrectomy", "With dialysis until the kidney heals", "At home without monitoring", "Conservatively with bed rest, monitoring and imaging"]'::jsonb, 3, 'Watch for falling Hb and increasing haematuria.', 'PON 423 · Urology'),
(1, 37, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'After radical cystectomy with ileal conduit, mucus in the urostomy bag is:', '["Always a sign of infection needing antibiotics", "Normal, from the bowel segment", "A sign of cancer recurrence", "A sign of kidney failure"]'::jsonb, 1, 'Encourage good fluid intake.', 'PON 423 · Urology'),
(1, 38, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'The balloon of a urinary catheter is normally inflated with:', '["Tap water 100 mL", "Normal saline 50 mL", "Sterile water, usually 10 mL", "Air, as it is lighter"]'::jsonb, 2, 'Follow the manufacturer''s stated volume.', 'PON 423 · Urology'),
(1, 39, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'Bipolar TURP using normal saline irrigation reduces the risk of:', '["TURP syndrome from hyponatraemia", "Infection of the prostate bed after surgery", "Retrograde ejaculation", "Bleeding completely"]'::jsonb, 0, 'Monopolar TURP requires non-conductive glycine.', 'PON 423 · Urology'),
(1, 40, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Urology', 'A double-J (JJ) ureteric stent:', '["Is a type of urinary catheter in the urethra", "Replaces the urethra", "Keeps the ureter open from kidney to bladder", "Drains urine from the bladder to the skin"]'::jsonb, 2, 'Patients must know when it is due for removal.', 'PON 423 · Urology'),
(1, 41, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Hyponatraemia after brain surgery is important because it can:', '["Worsen cerebral oedema and cause seizures", "Lower ICP", "Improve consciousness", "Prevent infection"]'::jsonb, 0, 'Causes include SIADH and cerebral salt wasting.', 'PON 423 · Neurosurgery'),
(1, 42, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Normal intracranial pressure in an adult is generally considered to be:', '["0–15 mmHg", "30–40 mmHg", "Above 25 mmHg at baseline", "50–60 mmHg"]'::jsonb, 0, 'Normal ICP in adults is typically cited as roughly 0–15mmHg; sustained pressures above about 20mmHg are generally considered pathological and require intervention.', 'PON 423 · Neurosurgery'),
(1, 43, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'What is the classic CT appearance of a subdural hematoma?', '["Crescent-shaped hyperdensity", "Star-shaped lucency", "Round calcified mass", "Biconvex (lens-shaped) hyperdensity"]'::jsonb, 0, 'Because subdural blood spreads freely along the brain surface rather than being confined by dural attachments, it forms a crescent-shaped collection on CT, unlike the biconvex shape of epidural hematomas.', 'PON 423 · Neurosurgery'),
(1, 44, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient with a new spinal cord injury and SBP 80 with HR 45 is likely in:', '["Septic shock", "Hypovolaemic shock only", "Cardiogenic shock", "Neurogenic shock"]'::jsonb, 3, 'Treat with fluids, vasopressors and atropine if needed.', 'PON 423 · Neurosurgery'),
(1, 45, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Cushing''s triad, a late sign of raised intracranial pressure, consists of:', '["Normal vital signs with confusion", "Hypotension, bradycardia, and regular respirations", "Hypotension, tachycardia, and tachypnoea", "Hypertension, bradycardia, and irregular respirations"]'::jsonb, 3, 'Cushing''s triad — widened pulse pressure/hypertension, bradycardia, and irregular respiratory pattern — reflects the body''s response to significantly raised intracranial pressure and impending herniation, a late and ominous sign.', 'PON 423 · Neurosurgery'),
(1, 46, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Before brain surgery, the nurse confirms the operative side by:', '["Looking at the theatre list only", "Asking the porter", "Checking imaging, consent and site marking", "Guessing from the symptoms"]'::jsonb, 2, 'Wrong-side surgery is a never event.', 'PON 423 · Neurosurgery'),
(1, 47, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', '24 hours after a head injury, a patient develops slurred speech and disorientation. The nurse''s initial action is to:', '["Inform the neurosurgeon of the patient''s status", "Prepare the patient for emergency surgery", "Continue hourly neurological assessments", "Recheck neurological status in 15 minutes"]'::jsonb, 0, 'New slurred speech and disorientation 24 h after a head injury mean neurological deterioration, possibly an expanding haematoma. Inform the neurosurgeon at once.', 'PON 423 · Neurosurgery'),
(1, 48, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Neurogenic bladder after spinal cord injury is often managed with:', '["Ignoring it", "Diuretics", "Fluid restriction only", "Intermittent catheterisation"]'::jsonb, 3, 'This lowers the risk of infection and kidney damage.', 'PON 423 · Neurosurgery'),
(1, 49, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient after anterior cervical discectomy develops neck swelling and breathing difficulty. The nurse suspects:', '["Hunger", "Normal swelling", "A neck haematoma compressing the airway", "Constipation"]'::jsonb, 2, 'Call for urgent help; the wound may need opening.', 'PON 423 · Neurosurgery'),
(1, 50, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient with a spinal cord injury at C4 or above is at high risk of:', '["Respiratory failure due to loss of diaphragm function", "Normal breathing", "Hearing loss", "Hand weakness only"]'::jsonb, 0, 'The phrenic nerve arises from C3–C5.', 'PON 423 · Neurosurgery'),
(1, 51, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Pupil assessment in neurosurgical patients includes size, shape and:', '["Tear volume", "Eyelash length", "Eye colour", "Reaction to light"]'::jsonb, 3, 'A sluggish pupil may be an early sign of raised ICP.', 'PON 423 · Neurosurgery'),
(1, 52, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A child with hydrocephalus before shunt surgery may show:', '["A small head", "A sunken fontanelle", "An enlarging head and bulging fontanelle with ''sunset eyes''", "Normal head growth"]'::jsonb, 2, 'Measure head circumference daily.', 'PON 423 · Neurosurgery'),
(1, 53, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'After craniotomy, a patient''s urine output rises to 300 mL/h with high serum sodium. The nurse suspects:', '["SIADH", "Acute kidney injury", "Heart failure", "Diabetes insipidus"]'::jsonb, 3, 'Report it; desmopressin may be needed.', 'PON 423 · Neurosurgery'),
(1, 54, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'After aneurysm clipping or coiling for subarachnoid haemorrhage, the nurse watches for delayed cerebral ischaemia, which peaks around:', '["Days 4–14", "The first hour only", "2 years later", "6 months later"]'::jsonb, 0, 'Nimodipine and good hydration are used to reduce the risk.', 'PON 423 · Neurosurgery'),
(1, 55, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient with raised ICP should avoid:', '["Normal oxygen levels", "Coughing, straining and lying flat with the neck flexed", "Good pain control", "Head of bed at 30 degrees"]'::jsonb, 1, 'These raise intrathoracic or venous pressure.', 'PON 423 · Neurosurgery'),
(1, 56, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Chronic subdural haematoma in the elderly is often drained by:', '["Lumbar puncture", "Medication only", "Burr holes", "Craniectomy in all cases"]'::jsonb, 2, 'Recurrence is possible; monitor for confusion.', 'PON 423 · Neurosurgery'),
(1, 57, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A ventriculoperitoneal shunt that is blocked typically presents with:', '["Itching only", "Joint pain", "Low blood pressure and diarrhoea", "Headache, vomiting, drowsiness and signs of raised ICP"]'::jsonb, 3, 'In infants, a bulging fontanelle and increasing head size.', 'PON 423 · Neurosurgery'),
(1, 58, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Immediately following a complete spinal cord injury, a patient may show flaccid paralysis and complete absence of reflexes below the level of injury. This temporary phenomenon is known as', '["autonomic dysreflexia", "spinal shock", "decerebrate posturing", "neurogenic shock"]'::jsonb, 1, 'Spinal shock is a temporary physiological state following acute spinal cord injury characterized by flaccid paralysis, areflexia, and loss of sensation below the injury level; reflexes typically return, often becoming hyperreflexic, over days to weeks.', 'PON 423 · Neurosurgery'),
(1, 59, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A child with myelomeningocele is nursed before closure in the:', '["Sitting position", "Prone or side-lying position to protect the sac", "Supine position on the sac", "Upright standing position"]'::jsonb, 1, 'Keep the sac moist and sterile.', 'PON 423 · Neurosurgery'),
(1, 60, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'In a patient with sustained elevated intracranial pressure, funduscopic examination of the optic disc (via CN II) may reveal', '["miosis unresponsive to light", "nystagmus on lateral gaze only", "corneal clouding", "papilledema (optic disc swelling)"]'::jsonb, 3, 'Chronically raised ICP impairs axoplasmic flow and venous return along the optic nerve sheath, causing swelling of the optic disc (papilledema), a key finding on fundoscopy.', 'PON 423 · Neurosurgery'),
(1, 61, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Video-assisted thoracoscopic surgery (VATS) compared with open thoracotomy usually gives:', '["More pain and longer stay", "Less pain and quicker recovery", "Larger scars", "Higher infection rates"]'::jsonb, 1, 'It is used for lung biopsy, lobectomy and pleural procedures.', 'PON 423 · Cardiothoracic Surgery'),
(1, 62, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Cardioplegia solution is used during heart surgery to:', '["Replace blood", "Increase heart rate", "Dissolve clots", "Stop the heart and protect the myocardium"]'::jsonb, 3, 'It is usually cold and high in potassium.', 'PON 423 · Cardiothoracic Surgery'),
(1, 63, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Tidaling (fluctuation) of fluid in the water-seal chamber with respiration indicates:', '["Complete lung re-expansion with no further monitoring needed", "Normal function; the tube is patent and communicating with the pleural space", "A malfunctioning chest tube system requiring immediate replacement", "Active hemorrhage into the chest tube"]'::jsonb, 1, 'Tidaling reflects normal pressure changes transmitted through a patent tube during respiration; its absence may indicate tube obstruction or full lung re-expansion.', 'PON 423 · Cardiothoracic Surgery'),
(1, 64, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Pleurodesis is performed to:', '["Drain the heart", "Repair a rib", "Stick the pleural layers together to prevent recurrent effusion or pneumothorax", "Remove a lung"]'::jsonb, 2, 'Talc or surgical abrasion is used; it can be painful.', 'PON 423 · Cardiothoracic Surgery'),
(1, 65, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Thoracotomy is generally indicated for massive haemothorax when drainage exceeds:', '["Any amount of blood at all", "100ml total", ">1500ml or >200ml/hr for 3 hours", "50ml/hr for 1 hour"]'::jsonb, 2, 'These specific volume thresholds indicate ongoing significant bleeding that chest tube drainage alone won''t control.', 'PON 423 · Cardiothoracic Surgery'),
(1, 66, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A patient s/p CABG has mediastinal tube drainage of 200 mL/hr. The nurse should:', '["Administer protamine", "Notify the surgeon", "Increase suction", "Clamp the tube"]'::jsonb, 1, '>100-200 mL/hr drainage may indicate bleeding; urgent intervention is needed.', 'PON 423 · Cardiothoracic Surgery'),
(1, 67, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Following chest tube insertion for a pneumothorax, continuous bubbling in the water-seal chamber that persists beyond the initial insertion period indicates:', '["A normal expected finding requiring no action", "A persistent air leak from the lung or a loose connection in the system", "Suction malfunction that should be corrected by increasing suction", "Resolution of the pneumothorax"]'::jsonb, 1, 'Continuous bubbling in the water-seal chamber beyond initial insertion indicates an ongoing air leak, either from the lung parenchyma or a loose tubing connection, requiring assessment.', 'PON 423 · Cardiothoracic Surgery'),
(1, 68, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Bronchopleural fistula is a particularly dangerous complication after which surgery?', '["Thyroidectomy", "Pneumonectomy for TB", "Cholecystectomy", "Appendectomy"]'::jsonb, 1, 'A leak between airway and empty pleural space after whole-lung removal can flood the remaining lung.', 'PON 423 · Cardiothoracic Surgery'),
(1, 69, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'After pneumonectomy, the patient is commonly positioned:', '["On the back or on the operated side, not the remaining lung side", "Only on the remaining (good) lung side", "Prone", "Head down"]'::jsonb, 0, 'This allows the good lung to expand fully.', 'PON 423 · Cardiothoracic Surgery'),
(1, 70, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Immediately after the insertion of a chest tube, vital signs should be monitored at what rate?', '["15 minutes for 2 hours", "15 minutes for 1 hour", "15 minutes for 4 hours", "15 minutes for 3 hours"]'::jsonb, 1, 'Vital signs are typically checked every 15 minutes for the first hour after chest tube insertion.', 'PON 423 · Cardiothoracic Surgery'),
(1, 71, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Atrial fibrillation after cardiac surgery is most common around:', '["Day 2–4 after surgery", "1 year later", "6 months later", "The first 5 minutes"]'::jsonb, 0, 'Correct potassium and magnesium; rate or rhythm control may be needed.', 'PON 423 · Cardiothoracic Surgery'),
(1, 72, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Mediastinal drains after cardiac surgery are placed to drain:', '["Bile", "Air from the lung only", "Blood from around the heart", "Urine"]'::jsonb, 2, 'Blocked drains can lead to tamponade.', 'PON 423 · Cardiothoracic Surgery'),
(1, 73, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Oesophagectomy patients are at particular risk after surgery of:', '["Kidney stones", "Joint pain", "Anastomotic leak and aspiration", "Hearing loss"]'::jsonb, 2, 'Nil by mouth and nasogastric tube are often kept for some days.', 'PON 423 · Cardiothoracic Surgery'),
(1, 74, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'The most common complication following thoracotomy is:', '["Atelectasis", "Wound dehiscence", "Pericardial tamponade", "Bronchopleural fistula"]'::jsonb, 0, 'Pain-limited shallow breathing and poor cough lead to mucus build-up and lung collapse.', 'PON 423 · Cardiothoracic Surgery'),
(1, 75, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A patient with a chest tube is being prepared for transport. Before transport, the nurse should:', '["Remove the chest tube", "Ensure the UWSD system is below the level of the patient''s chest", "Disconnect the UWSD system", "Clamp the chest tube for the duration of the transport"]'::jsonb, 1, 'The UWSD system must remain below the level of the chest to use gravity to facilitate drainage. Clamping the tube is generally contraindicated unless a specific protocol is in place, as it can cause a tension pneumothorax. Disconnecting or removing the tube is also unsafe.', 'PON 423 · Cardiothoracic Surgery'),
(1, 76, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Which site is commonly used for chest tube insertion?', '["Midline of the abdomen", "4th intercostal space, midclavicular line", "5th intercostal space, mid-axillary line", "Clavicular notch"]'::jsonb, 2, 'Chest drains usually go in the "safe triangle": 4th–5th intercostal space, mid-axillary line.', 'PON 423 · Cardiothoracic Surgery'),
(1, 77, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Temporary epicardial pacing wires are usually removed:', '["Never", "In theatre at the end of surgery", "After one year", "Several days after surgery, before anticoagulation peaks"]'::jsonb, 3, 'Watch for tamponade after removal.', 'PON 423 · Cardiothoracic Surgery'),
(1, 78, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'What is the primary purpose of the underwater seal in a UWSD system?', '["To apply negative pressure to the chest cavity", "To prevent air from re-entering the pleural space", "To collect the drainage from the pleural space", "To measure the amount of fluid drained from the chest"]'::jsonb, 1, 'The water seal acts as a one-way valve, allowing air and fluid to exit the chest cavity but preventing air from being sucked back in, which would worsen the pneumothorax.', 'PON 423 · Cardiothoracic Surgery'),
(1, 79, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A flail chest occurs when:', '["The sternum is bruised", "One rib is cracked", "The diaphragm is paralysed", "Two or more ribs are broken in two or more places"]'::jsonb, 3, 'The segment moves paradoxically on breathing.', 'PON 423 · Cardiothoracic Surgery'),
(1, 80, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'After pneumonectomy, chest drains (if present) are usually:', '["Clamped or on a balanced system, not on suction", "Left disconnected", "Removed during surgery always", "On high suction at all times"]'::jsonb, 0, 'Suction may shift the mediastinum.', 'PON 423 · Cardiothoracic Surgery'),
(1, 81, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Nutrition, smoking cessation and glucose control before plastic surgery improve:', '["Wound and flap healing", "Hearing", "Hair growth", "Vision"]'::jsonb, 0, 'Smoking constricts blood vessels and harms flaps.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 82, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Dog bites to the hand are at high risk of infection, so treatment includes:', '["Thorough wound cleaning, antibiotics and often delayed closure", "Immediate tight closure without cleaning", "Steroid cream", "No treatment"]'::jsonb, 0, 'Consider rabies and tetanus prophylaxis.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 83, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The ''position of comfort'' for a burned neck is usually avoided because it leads to:', '["Flexion contracture", "Hearing loss", "Extension contracture", "Hair loss"]'::jsonb, 0, 'Keep the neck extended with no pillow.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 84, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A pale, cool free flap with slow capillary refill suggests:', '["Infection only", "Arterial insufficiency", "Venous congestion", "Normal flap"]'::jsonb, 1, 'Inform the surgeon urgently; the flap may need re-exploration.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 85, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient with facial burns should be nursed with the head of the bed raised to:', '["Make eating easier only", "Increase fluid loss", "Reduce facial and airway swelling", "Prevent hearing loss"]'::jsonb, 2, 'Watch closely for airway compromise.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 86, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A burn patient with hyperkalemia likely has:', '["Hypoglycemia", "Cell lysis", "Over-resuscitation", "Metabolic alkalosis"]'::jsonb, 1, 'Burn tissue releases potassium into circulation.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 87, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient with 40% total body surface area burns is being resuscitated using the Parkland formula. If the patient weighs 70kg, the total fluid requirement for the first 24 hours is calculated as:', '["4 x 70 x 40 = 11,200ml", "70 x 40 = 2,800ml only", "4 x 40 = 160ml", "No formula is used for burns"]'::jsonb, 0, 'The Parkland formula is 4ml x weight(kg) x %TBSA burned = total 24-hour fluid requirement; here 4 x 70 x 40 = 11,200ml, with half given in the first 8 hours.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 88, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The emergent phase of burns lasts:', '[">3 weeks", "3-7 days", "1-3 weeks", "0-48 hours"]'::jsonb, 3, 'The emergent phase (0-48 hours) focuses on fluid resuscitation and airway management.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 89, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A meshed skin graft is used mainly to:', '["Improve the cosmetic result on the face", "Make the graft thicker", "Avoid the need for dressings", "Cover a larger area and allow fluid to drain"]'::jsonb, 3, 'It leaves a mesh-patterned scar.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 90, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The two drugs used together to manage the hypermetabolic response in burns are:', '["Insulin and glucagon", "Adrenaline and atropine", "Furosemide and spironolactone", "Propranolol and oxandrolone"]'::jsonb, 3, 'A beta-blocker (propranolol) reduces the hyperdynamic cardiovascular response, while an anabolic steroid (oxandrolone) helps counter the muscle-wasting hypermetabolic state.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 91, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A burns patient with escharotomy wounds should be monitored for:', '["Hair growth", "Visual loss only", "Hearing loss", "Bleeding and improved circulation or breathing"]'::jsonb, 3, 'Escharotomy relieves constriction from rigid eschar.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 92, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Breast reduction surgery is commonly done to relieve:', '["Breast cancer in all cases", "Back and neck pain from very large breasts", "Infertility", "Asthma"]'::jsonb, 1, 'Nipple sensation and breastfeeding may be affected.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 93, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A hand injury involving a tendon should be explored and repaired:', '["By a specialist in theatre", "Only after 6 months", "Never, as tendons heal alone", "At home by the patient"]'::jsonb, 0, 'Early repair gives better function.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 94, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Replantation of an amputated finger is more likely to succeed if the part is:', '["Placed directly on ice", "Placed in alcohol", "Kept cool, not frozen, and the patient reaches theatre quickly", "Left at room temperature in the open"]'::jsonb, 2, 'Wrap in moist gauze, place in a bag, then on ice.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 95, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The burn zone that is the main target of treatment, since it may still be saved, is the:', '["Zone of necrosis", "Zone of hyperaemia", "Zone of coagulation", "Zone of stasis"]'::jsonb, 3, 'The centre is already dead and the outer zone heals alone — the middle zone can go either way depending on care quality.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 96, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Hypertrophic scars differ from keloids because hypertrophic scars:', '["Occur only on the chest", "Stay within the original wound margins", "Never improve", "Spread beyond the wound edges"]'::jsonb, 1, 'Keloids extend beyond the wound and often recur after excision.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 97, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A ''Z-plasty'' revision of a burns scar helps to:', '["Treat infection", "Remove all scar tissue", "Release a contracture and lengthen the scar", "Make the scar shorter and tighter"]'::jsonb, 2, 'It changes the direction of the scar.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 98, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient with a new free flap is kept warm and well hydrated mainly to:', '["Maintain flap blood flow", "Prevent nausea", "Reduce pain only", "Help sleep"]'::jsonb, 0, 'Avoid vasoconstriction from cold, pain and dehydration.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 99, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The Curreri formula for nutritional requirements in burns patients is:', '["25kcal×kg + 40kcal×%TBSA", "4ml×kg×%TBSA", "10kcal×kg only", "2000kcal fixed daily"]'::jsonb, 0, 'This formula accounts for both baseline needs (per kg) and the extra hypermetabolic demand created by the burn itself (per %TBSA).', 'PON 423 · Reconstructive (Plastic) Surgery'),
(1, 100, 'Perioperative Mock — Day 4 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A flap used to close a sacral pressure ulcer must be protected after surgery by:', '["Using tight bandages", "Not turning the patient", "Avoiding pressure on the flap and using a special mattress", "Sitting the patient on it immediately"]'::jsonb, 2, 'Good nutrition helps healing.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(2, 1, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A patient after maxillofacial surgery is nursed with the head elevated mainly to:', '["Increase bleeding", "Reduce facial swelling and help breathing", "Improve hearing and drainage from the ears", "Help sleep only"]'::jsonb, 1, 'Cold compresses may also reduce swelling.', 'PON 417 · Maxillofacial Surgery'),
(2, 2, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Oral squamous cell carcinoma risk factors in Nigeria include:', '["Eating vegetables", "Regular exercise", "Tobacco, alcohol and poor oral hygiene", "Drinking clean water and eating fresh fruit"]'::jsonb, 2, 'Non-healing ulcers over 3 weeks need biopsy.', 'PON 417 · Maxillofacial Surgery'),
(2, 3, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Tetanus prophylaxis should be checked in patients with:', '["Facial lacerations contaminated with soil", "Normal tooth brushing", "Routine eye tests and dental check-ups only", "Clean dental fillings"]'::jsonb, 0, 'Give vaccine or immunoglobulin as appropriate.', 'PON 417 · Maxillofacial Surgery'),
(2, 4, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Pericoronitis is inflammation around:', '["The parotid gland", "The nasal septum", "The tonsils on both sides of the throat", "A partially erupted wisdom tooth"]'::jsonb, 3, 'It can spread to fascial spaces if untreated.', 'PON 417 · Maxillofacial Surgery'),
(2, 5, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Osteoradionecrosis of the jaw is a complication of:', '["A fracture of the femur", "Chickenpox in early childhood", "Simple tooth decay", "Radiotherapy to the head and neck"]'::jsonb, 3, 'Avoid dental extractions after radiotherapy if possible.', 'PON 417 · Maxillofacial Surgery'),
(2, 6, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Numbness of the lower lip and chin after a mandibular fracture is due to injury of the:', '["Lingual nerve only", "Accessory nerve", "Inferior alveolar nerve", "Facial nerve (cranial nerve VII)"]'::jsonb, 2, 'It runs in the mandibular canal.', 'PON 417 · Maxillofacial Surgery'),
(2, 7, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'During submandibular gland excision, the nerve at risk causing lower lip weakness is the:', '["Radial nerve", "Optic nerve behind the eye", "Marginal mandibular branch of the facial nerve", "Phrenic nerve"]'::jsonb, 2, 'The lingual and hypoglossal nerves are also at risk.', 'PON 417 · Maxillofacial Surgery'),
(2, 8, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Alveolar bone grafting in cleft patients is usually done:', '["In old age", "At birth, at the same time as the lip repair", "At 3 months with lip repair", "Before the permanent canine tooth erupts (around 8–11 years)"]'::jsonb, 3, 'It supports tooth eruption and closes the gap.', 'PON 417 · Maxillofacial Surgery'),
(2, 9, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Milky fluid in the neck drain after left neck dissection suggests:', '["Chyle leak from the thoracic duct", "Saliva leaking from the submandibular gland", "Normal serous drainage", "Infection with pus only"]'::jsonb, 0, 'Treatment includes low-fat diet or surgery.', 'PON 417 · Maxillofacial Surgery'),
(2, 10, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Orthognathic surgery patients may have elastics on the teeth after surgery to:', '["Prevent infection", "Reduce pain completely", "Guide the bite into the new position", "Feed the patient through the gaps between the teeth"]'::jsonb, 2, 'Scissors or cutters should be at the bedside.', 'PON 417 · Maxillofacial Surgery'),
(2, 11, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A free fibula flap is commonly used to reconstruct the:', '["Eyelid", "Mandible", "Nose tip", "Ear (pinna)"]'::jsonb, 1, 'It provides bone with its own blood supply.', 'PON 417 · Maxillofacial Surgery'),
(2, 12, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Bleeding from a tooth socket after extraction is first managed by:', '["Sucking through a straw and rinsing hard with hot water", "Applying heat to the cheek", "Biting on a folded gauze pad for 20–30 minutes", "Rinsing hard with hot water"]'::jsonb, 2, 'Persistent bleeding may need sutures and haemostatic agents.', 'PON 417 · Maxillofacial Surgery'),
(2, 13, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A Le Fort II fracture is described as:', '["A fracture separating the whole face from the skull", "A fracture of the mandible only, at the angle", "A pyramidal fracture through the nasal bones and maxilla", "A horizontal fracture above the teeth only"]'::jsonb, 2, 'Le Fort III is craniofacial dysjunction.', 'PON 417 · Maxillofacial Surgery'),
(2, 14, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'The most common site of mandibular fracture is the:', '["Chin (symphysis) only", "Condyle and angle of the mandible", "Coronoid process only", "Maxillary sinus wall"]'::jsonb, 1, 'Fractures are often bilateral (e.g. angle and opposite condyle).', 'PON 417 · Maxillofacial Surgery'),
(2, 15, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Frey''s syndrome after parotidectomy causes:', '["Loss of hearing", "Loss of smell and taste on the operated side", "Facial bone pain", "Sweating and flushing of the cheek when eating"]'::jsonb, 3, 'It is due to misdirected nerve regrowth.', 'PON 417 · Maxillofacial Surgery'),
(2, 16, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A dental extraction in a patient on warfarin is usually safe if the INR is:', '["Above 8, as a higher INR protects against clots after extraction", "Within the target range (often below about 4), with local haemostatic measures", "Not checked at all", "Unknown"]'::jsonb, 1, 'Local measures include packing and sutures.', 'PON 417 · Maxillofacial Surgery'),
(2, 17, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'After a tooth extraction, the patient is advised not to rinse vigorously for 24 hours to:', '["Avoid dislodging the blood clot", "Prevent hunger and help eating", "Avoid dental caries", "Improve speech"]'::jsonb, 0, 'Warm salt-water rinses start the next day.', 'PON 417 · Maxillofacial Surgery'),
(2, 18, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A patient after jaw surgery who is unable to swallow saliva should be:', '["Given suction at the bedside and nursed head-up", "Laid flat on the back and given solid food to swallow", "Fed solids", "Left unattended"]'::jsonb, 0, 'Drooling may occur because of swelling.', 'PON 417 · Maxillofacial Surgery'),
(2, 19, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A Le Fort III fracture involves:', '["Only the alveolar process", "Only the nasal bones", "Separation of the facial skeleton from the skull base", "Only the mandible and the teeth"]'::jsonb, 2, 'There is a high risk of airway problems and CSF leak.', 'PON 417 · Maxillofacial Surgery'),
(2, 20, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A non-healing mouth ulcer for more than 3 weeks should be:', '["Ignored if it is not painful", "Burned with caustic soda", "Referred for biopsy to exclude cancer", "Treated with antibiotics for months"]'::jsonb, 2, 'Early diagnosis improves outcome.', 'PON 417 · Maxillofacial Surgery'),
(2, 21, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Trachoma control follows the SAFE strategy: Surgery, Antibiotics, Facial cleanliness and:', '["Eye patching for all children at night", "Environmental improvement", "Electric light", "Early cataract surgery"]'::jsonb, 1, 'Azithromycin mass treatment is used.', 'PON 417 · Ophthalmic Surgery'),
(2, 22, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A squint (strabismus) in children is treated early mainly to prevent:', '["Amblyopia (lazy eye)", "Glaucoma", "Cataract in the deviated eye", "Retinal detachment"]'::jsonb, 0, 'Treatment includes glasses, patching and surgery.', 'PON 417 · Ophthalmic Surgery'),
(2, 23, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Normal visual acuity is recorded on a Snellen chart as:', '["3/60", "1/60", "6/6", "6/60"]'::jsonb, 2, '6/60 means the person sees at 6 m what a normal eye sees at 60 m.', 'PON 417 · Ophthalmic Surgery'),
(2, 24, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Pilocarpine drops act by:', '["Killing bacteria on the cornea", "Numbing the cornea", "Dilating the pupil", "Constricting the pupil (miosis)"]'::jsonb, 3, 'They are used in some glaucoma cases.', 'PON 417 · Ophthalmic Surgery'),
(2, 25, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Laser peripheral iridotomy is used to:', '["Treat a corneal ulcer", "Prevent or treat angle-closure glaucoma", "Repair a detached retina", "Remove a cataract without an incision"]'::jsonb, 1, 'It creates a hole in the iris to allow fluid flow.', 'PON 417 · Ophthalmic Surgery'),
(2, 26, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Nitrous oxide anaesthesia must be avoided after intraocular gas injection because it:', '["Diffuses into the bubble and raises eye pressure", "Causes cataract formation in the lens", "Lowers blood sugar", "Causes conjunctivitis"]'::jsonb, 0, 'Patients often wear a warning wristband.', 'PON 417 · Ophthalmic Surgery'),
(2, 27, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Scleral buckling is a surgical treatment for:', '["Squint in children", "Pterygium", "Retinal detachment", "Cataract"]'::jsonb, 2, 'A band is placed around the eye to support the retina.', 'PON 417 · Ophthalmic Surgery'),
(2, 28, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Timolol eye drops should be used with caution in patients with:', '["High blood sugar only", "Asthma or bradycardia", "Skin rash", "Hearing loss"]'::jsonb, 1, 'Beta-blocker drops can be absorbed systemically.', 'PON 417 · Ophthalmic Surgery'),
(2, 29, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A chalazion is:', '["A corneal ulcer caused by bacteria", "A painless lump in the eyelid from a blocked meibomian gland", "An infection of the lacrimal sac", "A detached retina"]'::jsonb, 1, 'It may be treated by incision and curettage.', 'PON 417 · Ophthalmic Surgery'),
(2, 30, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Retrobulbar block for eye surgery carries a risk of:', '["Spinal headache", "Knee injury from the lithotomy position", "Hearing loss", "Retrobulbar haemorrhage and brainstem anaesthesia"]'::jsonb, 3, 'Monitor the patient closely after the block.', 'PON 417 · Ophthalmic Surgery'),
(2, 31, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Fluorescein dye in the eye is used to:', '["Treat bacterial infection of the conjunctiva", "Lower eye pressure", "Dilate the pupil", "Show corneal abrasions or ulcers under blue light"]'::jsonb, 3, 'Damaged areas stain green.', 'PON 417 · Ophthalmic Surgery'),
(2, 32, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Eye drops after cataract surgery usually include:', '["Atropine only", "No drops at all, as the eye heals on its own", "Pilocarpine only", "Antibiotic and steroid drops"]'::jsonb, 3, 'Teach correct technique and hand hygiene.', 'PON 417 · Ophthalmic Surgery'),
(2, 33, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A patient with a perforating eye injury should be kept:', '["Nil by mouth, with a rigid shield over the eye, ready for theatre", "Rubbing the eye to clear it", "Eating a normal diet with an eye pad pressed firmly", "Using steroid drops alone and pressing a firm pad onto the eye"]'::jsonb, 0, 'Avoid pressure on the eye.', 'PON 417 · Ophthalmic Surgery'),
(2, 34, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Primary open-angle glaucoma is often called the ''silent thief of sight'' because it:', '["Causes sudden painful red eye", "Causes gradual painless loss of side vision", "Causes loss of central vision first", "Is always present at birth and is easily seen"]'::jsonb, 1, 'Regular eye pressure checks help early detection.', 'PON 417 · Ophthalmic Surgery'),
(2, 35, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'After cataract surgery, the patient may notice:', '["Total blindness for a month", "Mild grittiness and blurred vision for a few days", "Severe pain as normal", "Loss of hearing in the ear on the same side"]'::jsonb, 1, 'Severe pain or worsening vision may mean infection.', 'PON 417 · Ophthalmic Surgery'),
(2, 36, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A sudden painless loss of vision in one eye with a ''cherry-red spot'' suggests:', '["Conjunctivitis", "Central retinal artery occlusion", "Mature cataract in the elderly", "Glaucoma"]'::jsonb, 1, 'It is an emergency; check for giant cell arteritis in older adults.', 'PON 417 · Ophthalmic Surgery'),
(2, 37, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Diabetic retinopathy is treated mainly with:', '["Laser photocoagulation or anti-VEGF injections", "Oral antibiotics", "Eye patching and oral antibiotics", "Cataract surgery only"]'::jsonb, 0, 'Good glucose and blood pressure control slow it.', 'PON 417 · Ophthalmic Surgery'),
(2, 38, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Phacoemulsification is a cataract operation that:', '["Treats glaucoma only", "Repairs the retina using a gas bubble and laser", "Breaks up the lens with ultrasound and replaces it with an artificial lens", "Removes the whole eye"]'::jsonb, 2, 'It uses a small incision and often local anaesthesia.', 'PON 417 · Ophthalmic Surgery'),
(2, 39, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Fungal keratitis is more common:', '["In newborns of mothers with gonorrhoea", "In people who never go outside", "After eye injury with plant or vegetable matter", "After cataract surgery only"]'::jsonb, 2, 'It is common in farmers in tropical countries.', 'PON 417 · Ophthalmic Surgery'),
(2, 40, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Pterygium is:', '["A triangular growth of conjunctiva onto the cornea", "A detached retina seen at the edge of the cornea", "A type of cataract", "An eyelid infection"]'::jsonb, 0, 'It is common in sunny, dusty climates and linked to UV exposure.', 'PON 417 · Ophthalmic Surgery'),
(2, 41, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Vertigo, nausea and nystagmus after ear surgery may be due to:', '["Low blood sugar only", "Bladder infection from the urinary catheter", "Inner ear (labyrinth) disturbance", "Wound infection of the abdomen"]'::jsonb, 2, 'Assist with mobilisation to prevent falls.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 42, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'The most common cause of a neck lump in a child is:', '["Reactive lymph nodes from infection", "Thyroid cancer spreading to the neck nodes", "Laryngeal cancer", "Salivary stones"]'::jsonb, 0, 'Persistent, hard or growing lumps need investigation.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 43, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After thyroid or neck surgery, the throat pack used during ENT surgery should be:', '["Counted and documented as removed", "Ignored, as it dissolves in the stomach", "Removed only the next day", "Left in place"]'::jsonb, 0, 'A retained throat pack causes airway obstruction.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 44, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Myringotomy is:', '["A small cut in the eardrum to drain fluid", "Removal of the larynx", "Removal of the tonsils", "Repair of a nasal fracture"]'::jsonb, 0, 'A grommet may be inserted.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 45, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Otitis externa is treated mainly with:', '["Grommets inserted through the eardrum", "Tonsillectomy", "Nasal packing", "Ear cleaning and antibiotic/steroid ear drops"]'::jsonb, 3, 'Keep the ear dry.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 46, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Acute sinusitis complications that need urgent care include:', '["Watery eyes only", "Orbital cellulitis and meningitis", "Sneezing and a mild runny nose only", "Mild nasal stuffiness"]'::jsonb, 1, 'Eye swelling with reduced vision is an emergency.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 47, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A child with obstructive sleep apnoea after adenotonsillectomy needs close monitoring because of:', '["Post-operative airway obstruction and opioid sensitivity", "Low risk of complications", "Hearing loss and ear infection", "High blood sugar"]'::jsonb, 0, 'Overnight observation is often needed.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 48, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Laser surgery of the airway requires a special tube because:', '["It has no cuff", "It is cheaper and easier to insert", "Ordinary tubes can ignite and cause an airway fire", "It is easier to insert"]'::jsonb, 2, 'Use laser-safe tubes and low oxygen concentration.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 49, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Microlaryngoscopy is used to:', '["Repair the nasal septum and turbinates", "Look at the stomach", "Examine and treat lesions of the larynx under a microscope", "Remove the tonsils"]'::jsonb, 2, 'Voice rest may be advised afterwards.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 50, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A nasal polyp is:', '["A soft, painless swelling from the nasal or sinus lining", "A type of tooth growing in the nose", "An ear infection", "A bony growth of the skull"]'::jsonb, 0, 'It is often linked to allergy or asthma.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 51, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Before ENT surgery under local anaesthetic with adrenaline, the nurse should check for:', '["Shoe size and height", "Blood group only", "Heart disease and maximum safe doses", "Hair colour"]'::jsonb, 2, 'Adrenaline can cause tachycardia and arrhythmias.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 52, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'The inner cannula of a tracheostomy tube is removed and cleaned mainly to:', '["Help speech only", "Prevent blockage with secretions", "Give drugs directly into the trachea", "Change the tube size"]'::jsonb, 1, 'Clean at least every 4–8 hours or as needed.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 53, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A thyroglossal cyst moves upward when the patient:', '["Turns the head to the other side", "Lifts the arms", "Closes the eyes", "Sticks out the tongue"]'::jsonb, 3, 'It is removed by Sistrunk''s operation.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 54, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Persistent hoarseness for more than 3 weeks in a smoker should be investigated to exclude:', '["Tonsillitis", "Laryngeal cancer", "Common cold", "Ear wax blocking the ear canal"]'::jsonb, 1, 'Refer for laryngoscopy.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 55, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Before the first tracheostomy tube change (usually after a week), the stoma tract is:', '["Not needed", "Closed completely and fully healed", "Fully formed on day 1", "Not yet fully formed, so changes are risky"]'::jsonb, 3, 'Tracheal dilators and an obturator should be at the bedside.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 56, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Malignant (necrotising) otitis externa is most common in:', '["Young athletes who swim often", "Elderly diabetic patients", "Healthy children", "Pregnant women only"]'::jsonb, 1, 'It needs prolonged IV antibiotics.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 57, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A patient with nasal packing should be watched for:', '["Hypoxia, aspiration and toxic shock syndrome", "Leg pain and deep vein thrombosis", "Hearing loss only", "Visual loss only"]'::jsonb, 0, 'Antibiotics may be given while the pack is in.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 58, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Posterior epistaxis that does not stop with anterior packing may need:', '["Ice cream and cold drinks, then discharge home", "A posterior nasal pack or balloon and admission", "Oral antibiotics only", "Discharge home with tissue paper"]'::jsonb, 1, 'Monitor airway, pulse and blood loss.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 59, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Post-tonsillectomy secondary haemorrhage usually occurs:', '["After 2 years", "5–10 days after surgery, often due to infection", "Never; bleeding only happens in the first hour", "In the first 5 minutes"]'::jsonb, 1, 'Advise patients to return immediately if bleeding occurs.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 60, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A coin seen on X-ray in a child''s oesophagus is removed by:', '["Endoscopy under general anaesthesia", "Laxatives and waiting for it to pass", "Forcing the child to swallow bread", "Waiting for 2 weeks"]'::jsonb, 0, 'Button batteries are an emergency.', 'PON 415 · Otorhinolaryngology (ENT)'),
(2, 61, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'The mnemonic ''IPPR'' used to systematically check a chest X-ray before interpretation stands for:', '["Imaging, Patient, Protocol, Report", "Infection, Pneumonia, Pleura, Ribs", "Intubation, Perfusion, Pressure, Recovery", "Inspiration, Position, Penetration, Rotation"]'::jsonb, 3, 'IPPR is the standard systematic check before reading a chest X-ray: adequate Inspiration, correct Position, correct Penetration (exposure), and no Rotation.', 'Radiology & Radiation Safety'),
(2, 62, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'An absolute contraindication to MRI scanning is:', '["A non-MRI-conditional cardiac pacemaker or ferromagnetic implant", "Mild claustrophobia", "Recent blood test", "Pregnancy in the second trimester (with appropriate precautions)"]'::jsonb, 0, 'Ferromagnetic implants or non-MRI-conditional devices such as certain pacemakers can be displaced or malfunction in the MRI''s strong magnetic field, making them absolute contraindications.', 'Radiology & Radiation Safety'),
(2, 63, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A classic chest X-ray sign of pleural effusion is:', '["Blunting of the costophrenic angle", "A widened mediastinum", "Free air under the diaphragm", "Hyperinflated lung fields"]'::jsonb, 0, 'Fluid accumulating in the pleural space characteristically blunts (obscures) the normally sharp costophrenic angle on an upright chest X-ray.', 'Radiology & Radiation Safety'),
(2, 64, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A transudate (clear fluid) on CT chest appears as:', '["Hyperdense with air densities", "Homogeneously hypodense with no strands", "Hypodense with strands", "Hyperdense with strands"]'::jsonb, 1, 'Simple transudate appears on CT as homogeneous low-density (water-density) fluid without septations or strands.', 'Radiology & Radiation Safety'),
(2, 65, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Which imaging modality is generally first-line for rapidly diagnosing acute intracranial haemorrhage?', '["Doppler flow study", "Ultrasound", "Plain X-ray of the skull", "CT scan"]'::jsonb, 3, 'CT scanning is fast and widely available, making it the first-line imaging choice for suspected acute intracranial haemorrhage.', 'Radiology & Radiation Safety'),
(2, 66, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Before a patient has a contrast CT, the nurse checks:', '["Kidney function, allergy history and metformin use", "Hair colour", "Shoe size", "Favourite food"]'::jsonb, 0, 'Contrast can harm kidneys and cause reactions.', 'Radiology & Radiation Safety'),
(2, 67, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'On an abdominal X-ray, a ''coffee bean sign'' is classically associated with which condition?', '["Simple constipation", "Normal bowel gas pattern", "Gallstones", "Sigmoid volvulus"]'::jsonb, 3, 'The ''coffee bean sign'' describes the characteristic dilated, twisted loop of bowel seen on abdominal X-ray in sigmoid volvulus.', 'Radiology & Radiation Safety'),
(2, 68, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'The first-line imaging investigation in suspected acute stroke is:', '["Non-contrast CT head", "Chest X-ray", "MRI with contrast", "Abdominal ultrasound"]'::jsonb, 0, 'Non-contrast CT head is performed urgently in suspected stroke primarily to exclude haemorrhage before considering thrombolytic therapy.', 'Radiology & Radiation Safety'),
(2, 69, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'On a plain abdominal X-ray, multiple dilated bowel loops with air-fluid levels on an erect film are classic findings of:', '["Gallstones", "Chronic constipation only", "Intestinal obstruction", "Normal bowel gas pattern"]'::jsonb, 2, 'Dilated, gas-filled bowel loops with air-fluid levels on an erect film are the classic radiographic sign of mechanical bowel obstruction.', 'Radiology & Radiation Safety'),
(2, 70, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Free air visible under the diaphragm on an erect chest/abdominal X-ray most strongly suggests:', '["Pulmonary embolism", "Perforation of a hollow viscus", "Chronic heart failure", "Normal post-prandial bowel gas"]'::jsonb, 1, 'Pneumoperitoneum (free sub-diaphragmatic air) is a classic sign of a perforated hollow abdominal organ and represents a surgical emergency.', 'Radiology & Radiation Safety'),
(2, 71, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A thyroid shield is worn by theatre staff during fluoroscopy to:', '["Keep the neck warm", "Protect the radiosensitive thyroid gland", "Prevent infection", "Support the head"]'::jsonb, 1, 'Lead glasses protect the eye lens.', 'Radiology & Radiation Safety'),
(2, 72, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Oral iodinated contrast carries a specific risk if aspirated, namely:', '["Immediate cardiac arrest", "Pulmonary oedema and chemical pneumonitis", "No risk at all — it is inert if aspirated", "Permanent loss of taste"]'::jsonb, 1, 'Aspiration of oral iodinated contrast can cause pulmonary oedema and chemical pneumonitis, which is why aspiration risk must be assessed before oral contrast is given.', 'Radiology & Radiation Safety'),
(2, 73, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Negative contrast agents (e.g. air, carbon dioxide) appear on imaging as:', '["Only visible on MRI, never on X-ray", "Identical in appearance to iodinated contrast", "Dark and lucent", "Dense and white (opaque)"]'::jsonb, 2, 'Negative contrast agents such as air or CO2 have low density and appear dark/lucent on radiographic images, the opposite of positive agents like barium or iodine.', 'Radiology & Radiation Safety'),
(2, 74, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'The ALARA principle in radiologic imaging stands for:', '["Always Limit Additional Radiographic Access", "As Low As Reasonably Achievable (radiation exposure)", "Any Level Achievable with Repeated Attempts", "A Legal Requirement for All Radiographs"]'::jsonb, 1, 'ALARA (''As Low As Reasonably Achievable'') guides minimising radiation exposure to patients and staff while still obtaining diagnostically useful images.', 'Radiology & Radiation Safety'),
(2, 75, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A pleural effusion typically becomes visible on a standard chest X-ray only once fluid volume reaches approximately:', '["150–300ml", "5–10ml", "There is no minimum volume — any amount is visible", "2–3 litres"]'::jsonb, 0, 'A pleural effusion generally needs to reach roughly 150–300ml before it becomes detectable on a standard chest X-ray.', 'Radiology & Radiation Safety'),
(2, 76, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Electrical equipment in theatre should be:', '["Used even with frayed cables", "Checked and tested regularly, with faults reported and removed from use", "Never inspected", "Repaired with tape by staff"]'::jsonb, 1, 'Faulty equipment can cause electric shock and fires.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 77, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Poor operating table height for the scrub nurse may cause:', '["Hearing loss", "Eye infection", "Skin cancer", "Neck, shoulder and back strain"]'::jsonb, 3, 'Adjust the table or use a platform.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 78, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'A safety data sheet (SDS) for a chemical gives information on:', '["Theatre schedules", "The supplier''s staff names", "Hazards, safe handling, first aid and disposal", "The chemical''s price"]'::jsonb, 2, 'It must be available for every hazardous substance.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 79, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Pre-employment health screening for theatre nurses mainly aims to:', '["Choose the nurse''s salary", "Decide their shift times", "Ensure fitness for the role and check immunisation status", "Replace training"]'::jsonb, 2, 'It protects both staff and patients.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 80, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Hepatitis B vaccination for theatre staff is followed by:', '["A hearing test", "A chest X-ray", "No follow-up ever", "A blood test to check antibody response"]'::jsonb, 3, 'Non-responders need further assessment.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 81, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'A slippery theatre floor after a spillage should be:', '["Left to dry by itself", "Ignored if the case is busy", "Cleaned immediately and marked with a warning sign", "Covered with paper towels only"]'::jsonb, 2, 'Slips and falls are common injuries.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 82, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Exposure to waste anaesthetic gases in pregnant staff is reduced by:', '["Using open-mask anaesthesia", "Turning off scavenging", "Opening the gas cylinders", "Effective scavenging and good ventilation"]'::jsonb, 3, 'Report any concerns to occupational health.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 83, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Noise in the operating theatre should be controlled mainly because it:', '["Helps patients sleep", "Has no effect", "Improves concentration", "Distracts staff and increases errors"]'::jsonb, 3, 'Limit alarms, music and conversations during critical steps.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 84, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'The ''hierarchy of controls'' for workplace hazards starts with:', '["Training only", "Warning signs", "Personal protective equipment", "Elimination of the hazard"]'::jsonb, 3, 'Then substitution, engineering controls, administrative controls and PPE.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 85, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'A nurse with an open cut on the hand should, before scrubbing:', '["Use alcohol on the cut and continue", "Hide it from the team", "Scrub as usual without a cover", "Report it and cover it with a waterproof dressing, or not scrub"]'::jsonb, 3, 'Broken skin increases the risk of bloodborne virus exposure.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 86, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'A radiation dosimeter badge worn by theatre staff measures:', '["Air temperature", "Hearing", "Blood pressure", "The radiation dose received over time"]'::jsonb, 3, 'Wear it under the lead apron at chest or waist level.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 87, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Musculoskeletal injuries in nurses are most often caused by:', '["Writing notes", "Lifting and moving patients", "Talking to patients", "Hand washing"]'::jsonb, 1, 'Use hoists, slide sheets and enough staff.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 88, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Before moving a heavy load, the nurse should first:', '["Lift alone without help", "Lift quickly to get it over with", "Assess the task, the load, the environment and individual ability", "Twist the back while lifting"]'::jsonb, 2, 'This is a manual handling risk assessment (TILE).', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 89, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Personal protective equipment is considered:', '["A substitute for safe systems", "Unnecessary in theatre", "The last line of defence against hazards", "The first and only control needed"]'::jsonb, 2, 'Other controls should be used first.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 90, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Formaldehyde used for specimens is hazardous because it is:', '["Irritant and a possible carcinogen", "A vitamin", "Safe to breathe", "Harmless to skin"]'::jsonb, 0, 'Use pre-filled containers and good ventilation.', 'GSO 410 · Occupational Health & Ergonomics'),
(2, 91, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'Henderson''s philosophy of nursing is most heavily influenced by which broader conceptual approach?', '["A model centered exclusively on environmental sanitation", "A needs-based, holistic approach similar in spirit to Maslow''s hierarchy of needs", "A strictly systems-based, energy-field approach", "A purely biomedical, disease-focused model excluding psychosocial needs"]'::jsonb, 1, 'Henderson''s 14 components reflect a holistic, needs-based approach to care that parallels the breadth of Maslow''s hierarchy, spanning physiological, safety, social, and self-actualizing needs.', 'Nursing Theories'),
(2, 92, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'Following successful treatment of a stressor reaction, a nurse focuses on rehabilitation and helping the client readapt to promote stability and prevent future reoccurrence of the stressor. This reflects which of Neuman''s prevention levels?', '["Primary prevention", "Secondary prevention", "Tertiary prevention", "Reconstitutive prevention only, unrelated to Neuman''s model"]'::jsonb, 2, 'Tertiary prevention occurs after secondary prevention/treatment and focuses on readaptation, reconstitution, and maintaining stability to prevent further regression or recurrence of the stressor reaction.', 'Nursing Theories'),
(2, 93, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'The environmental theory of nursing ("cleanliness is next to godliness") was put forward by:', '["Isaac Newton", "Abraham Maslow", "Virginia Henderson", "Florence Nightingale"]'::jsonb, 3, 'Florence Nightingale''s environmental theory stresses cleanliness, ventilation, light, warmth and quiet for healing.', 'Nursing Theories'),
(2, 94, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'Which of the following nursing models draws most directly and explicitly on general systems theory to describe the client as a system interacting with environmental stressors?', '["Henderson''s 14 Basic Needs", "Nightingale''s Environmental Theory", "Gordon''s Functional Health Patterns", "Neuman''s Systems Model"]'::jsonb, 3, 'Betty Neuman explicitly built her Systems Model on general systems theory, portraying the client as an open system with a core structure, lines of defense/resistance, and stressors from the environment.', 'Nursing Theories'),
(2, 95, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'A client develops an autoimmune reaction that attacks her own joint tissue. Using Neuman''s classification, this stressor would be categorized as:', '["Intrapersonal", "Suprapersonal", "Extrapersonal", "Interpersonal"]'::jsonb, 0, 'An intrapersonal stressor arises from within the individual, such as an internal physiological or emotional process; an autoimmune reaction occurring within the client''s own body fits this category.', 'Nursing Theories'),
(2, 96, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'Feedback shows that caring is a key element of practice. Which theorist best supports this concept?', '["Rogers", "Erikson", "Watson", "Maslow"]'::jsonb, 2, 'Jean Watson''s Theory of Human Caring makes caring central to nursing.', 'Nursing Theories'),
(2, 97, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'Neuman classifies stressors into three types based on their relationship to the client system. Which of the following correctly identifies them?', '["Universal, developmental, and health-deviation stressors", "Primary, secondary, and tertiary stressors", "Focal, contextual, and residual stressors", "Intrapersonal, interpersonal, and extrapersonal stressors"]'::jsonb, 3, 'Neuman categorizes stressors as intrapersonal (occurring within the person, e.g., an autoimmune response), interpersonal (occurring between individuals, e.g., role expectations), and extrapersonal (occurring outside the person, e.g., financial or environmental circumstances).', 'Nursing Theories'),
(2, 98, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'The self-care deficit theory was proposed by:', '["Dorothea Orem", "Betty Neuman", "Virginia Henderson", "Imogene King"]'::jsonb, 0, 'Dorothea Orem proposed the self-care deficit theory.', 'Nursing Theories'),
(2, 99, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'According to Orem, the sum of self-care actions required at a specific time to meet an individual''s known self-care requisites using appropriate methods is called the:', '["Adaptive coping mechanism", "Normal line of defense", "Functional health pattern", "Therapeutic self-care demand"]'::jsonb, 3, 'The therapeutic self-care demand is the totality of self-care actions to be performed for a specified period in order to meet an individual''s self-care requisites using valid methods and related sets of operations.', 'Nursing Theories'),
(2, 100, 'Perioperative Mock — Day 4 Afternoon (Nov 2026)', 'Nursing Theories', 'A nurse initiates prompt treatment after a client develops symptoms of a stressor reaction, aiming to reduce the effects and strengthen internal lines of resistance. This corresponds to which Neuman prevention level?', '["Secondary prevention", "Primary prevention", "Tertiary prevention", "Preventive maintenance"]'::jsonb, 0, 'Secondary prevention focuses on treatment of symptoms after a stressor has invaded the system and produced a reaction, aiming to strengthen the internal lines of resistance and restore stability.', 'Nursing Theories'),
(3, 1, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The reliability index obtained from a test–retest procedure is the:', '["Coefficient of equivalence", "Coefficient of stability", "Coefficient of rater stability", "Coefficient of internal consistency"]'::jsonb, 1, 'Test–retest reliability gives the coefficient of stability. Parallel forms give equivalence; Cronbach''s alpha gives internal consistency.', 'GST 403 · Research & Statistics'),
(3, 2, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Which scale of measurement captures data in mutually exclusive categories with no order?', '["Ordinal", "Interval", "Ratio", "Nominal"]'::jsonb, 3, 'The nominal scale puts data into mutually exclusive, unordered categories.', 'GST 403 · Research & Statistics'),
(3, 3, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The first step of research is:', '["Identifying a problem", "Collecting data", "Selecting a design", "Finding a solution"]'::jsonb, 0, 'The research process begins with identifying a problem.', 'GST 403 · Research & Statistics'),
(3, 4, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'When a distribution is symmetrical and unimodal:', '["The mean, median and mode are the same", "The median is greater than the mean", "The mean is greater than the mode", "The mode is greater than the median"]'::jsonb, 0, 'In a symmetrical, unimodal (normal) distribution, the mean, median and mode are equal.', 'GST 403 · Research & Statistics'),
(3, 5, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Which is a characteristic of quantitative research?', '["A large sample is emphasised", "There are multiple subjective realities", "No generalisation is made from the findings", "Data are reported in a literary style"]'::jsonb, 0, 'Quantitative research stresses large, representative samples and generalisation. Multiple subjective realities and literary reporting are qualitative features.', 'GST 403 · Research & Statistics'),
(3, 6, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'In the PICO framework for developing a clinical research question, the letters stand for:', '["Plan, Implement, Coordinate, Overview", "Patient, Illness, Cure, Observation", "Population, Intervention, Comparison, Outcome", "Problem, Investigation, Cost, Objective"]'::jsonb, 2, 'PICO structures a clinical question around Population (or patient), Intervention, Comparison, and Outcome, helping focus literature searches and research design.', 'GST 403 · Research & Statistics'),
(3, 7, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The difference between experimental and quasi-experimental designs is that:', '["Experimental designs lack a control group", "Quasi-experimental designs lack randomisation while experimental designs have it", "Quasi-experimental designs have randomisation and experimental designs do not", "Experimental designs have control but quasi-experiments have randomisation"]'::jsonb, 1, 'Quasi-experiments manipulate an independent variable but lack randomisation, and sometimes a control group. True experiments have both.', 'GST 403 · Research & Statistics'),
(3, 8, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Which is NOT a measure of dispersion?', '["Range", "Mean", "Standard deviation", "Variance"]'::jsonb, 1, 'Range, variance and standard deviation measure dispersion. The mean measures central tendency.', 'GST 403 · Research & Statistics'),
(3, 9, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The less variation an instrument produces in repeated measurements of an attribute, the higher its:', '["Sensitivity", "Validity", "Relativity", "Reliability"]'::jsonb, 3, 'Reliability is consistency: less variation on repeated measurement means higher reliability.', 'GST 403 · Research & Statistics'),
(3, 10, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Failure to acknowledge borrowed material (using others'' work as one''s own) is called:', '["Footnote", "Plagiarism", "Acknowledgement", "Index"]'::jsonb, 1, 'Plagiarism is presenting someone else''s work or ideas as your own without acknowledgement.', 'GST 403 · Research & Statistics'),
(3, 11, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', '______ describes the present state of affairs as it exists without having any control over variables.', '["Distinctive research", "Analytical research", "Applied research", "Descriptive research"]'::jsonb, 3, 'Descriptive research describes existing conditions without manipulating variables.', 'GST 403 · Research & Statistics'),
(3, 12, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Which of the following is a non-probability sampling method?', '["Stratified", "Cluster", "Simple random", "Snowball"]'::jsonb, 3, 'Snowball sampling (participants recruit others) is non-probability. Random, cluster and stratified sampling are probability methods.', 'GST 403 · Research & Statistics'),
(3, 13, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A study finds a statistically significant but very small difference between two treatments (e.g. a 1% difference in outcome) in a very large sample. This illustrates the important distinction between:', '["Statistical significance and clinical significance/relevance", "Ethics and methodology", "Reliability and validity, which are unrelated concepts here", "Qualitative and quantitative research"]'::jsonb, 0, 'A statistically significant result (often achievable with large samples even for tiny differences) does not automatically mean the finding is clinically meaningful — this distinction is important when interpreting research.', 'GST 403 · Research & Statistics'),
(3, 14, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Which is NOT a probability sampling method?', '["Cluster sampling", "Convenience sampling", "Simple random sampling", "Stratified random sampling"]'::jsonb, 1, 'Convenience sampling is non-probability. Simple random, cluster and stratified sampling give every unit a known chance of selection.', 'GST 403 · Research & Statistics'),
(3, 15, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'All arithmetic operations (add, subtract, multiply, divide) can be performed on which scale?', '["Nominal", "Ordinal", "Interval", "Ratio"]'::jsonb, 3, 'Only the ratio scale has a true zero, so all arithmetic, including ratios, is meaningful (e.g. weight, height).', 'GST 403 · Research & Statistics'),
(3, 16, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'Mr Zee says his heart pounds and he is short of breath on the stairs. The nurse then auscultates the heart and checks the pulse. The nurse is:', '["Validating data", "Collecting data", "Processing data into information", "Organising data"]'::jsonb, 0, 'Checking pulse and heart sounds to confirm a subjective complaint (palpitations, breathlessness) is validating data.', 'Nursing Process'),
(3, 17, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'A client reports difficulty falling asleep, frequent nighttime awakenings, and feeling unrested in the morning. Which Gordon functional health pattern is being assessed?', '["Value-belief pattern", "Sleep-rest pattern", "Coping-stress tolerance pattern", "Cognitive-perceptual pattern"]'::jsonb, 1, 'The sleep-rest pattern addresses the client''s pattern of sleep, rest, and relaxation, including any sleep disturbances and the client''s perception of adequate rest.', 'Nursing Process'),
(3, 18, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'The 4 skills used in evaluation are:', '["Palpation, Auscultation, Percussion, Inspection", "Observation, Interviewing, Record keeping, Interpretation", "Diagnosis, Planning, Implementation, Discharge", "Prescribing, Administering, Charting, Billing"]'::jsonb, 1, 'These four skills together let the nurse gather and make sense of information about how the patient is progressing.', 'Nursing Process'),
(3, 19, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'The first component of a nursing diagnosis statement is the:', '["Related factors", "Signs and symptoms", "Problem", "Etiology"]'::jsonb, 2, 'A nursing diagnosis statement begins with the Problem (diagnostic label), then the Etiology and the Signs/Symptoms (PES).', 'Nursing Process'),
(3, 20, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'Evaluation in the nursing process is best described as:', '["An ongoing procedure of re-assessment", "Unrelated to the original care plan", "Something done only by physicians", "A one-time final step only"]'::jsonb, 0, 'Evaluation happens continuously throughout care, essentially repeating the assessment step to check progress against the plan.', 'Nursing Process'),
(3, 21, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'The assessment approach in which the cardiovascular system is assessed before the genito-urinary system is the:', '["Cephalocaudal approach", "Systematic approach", "Body systems approach", "Approach by order of priority"]'::jsonb, 2, 'The body systems approach assesses one system at a time, e.g. cardiovascular before genito-urinary.', 'Nursing Process'),
(3, 22, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'Which conceptual framework organizes assessment data into categories such as Health Perception-Health Management, Nutritional-Metabolic, and Elimination patterns?', '["Roy''s Adaptation Model", "Maslow''s Hierarchy of Needs", "Orem''s Self-Care Model", "Gordon''s Functional Health Patterns"]'::jsonb, 3, 'Gordon''s Functional Health Patterns is a widely used framework for organizing assessment data into 11 categories including health perception and nutrition.', 'Nursing Process'),
(3, 23, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'During evaluation you find two client goals have not been met. What is the best action?', '["Reassess the problem, review the care plan and revise as needed", "Stop working on these goals, as evaluation is the last step", "Discharge the client", "Assess only the client''s motivation"]'::jsonb, 0, 'When goals are not met, the nurse reassesses, finds out why, and revises the care plan. The nursing process is cyclical.', 'Nursing Process'),
(3, 24, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'Which is necessary for making a nursing diagnosis?', '["Designing the care plan", "Performing activities", "Clustering of cues", "Validating the plan"]'::jsonb, 2, 'Grouping related assessment cues (clustering) shows the patterns that support a nursing diagnosis.', 'Nursing Process'),
(3, 25, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'The nurse is assessing a postoperative adult patient. Which of the following should the nurse document as subjective data?', '["Laboratory test result", "Patient’s description of pain", "Vital signs", "Electrocardiographic (ECG) waveforms"]'::jsonb, 1, 'Subjective data are what the patient reports, such as pain. Vital signs, ECGs and lab results are objective.', 'Nursing Process'),
(3, 26, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'Which of the following NANDA-I diagnoses is classified as a ''Health Promotion'' diagnosis rather than a problem-focused or risk diagnosis?', '["Ineffective Coping", "Decisional Conflict", "Readiness for Enhanced Coping", "Risk for Ineffective Coping"]'::jsonb, 2, 'Health promotion diagnoses describe a patient''s motivation and desire to increase well-being; Readiness for Enhanced Coping reflects a patient actively wanting to strengthen an already adequate coping pattern.', 'Nursing Process'),
(3, 27, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'Which activity best describes the evaluation phase?', '["Carry out nursing procedures and document", "Interpret data and identify client problems", "Establish short- and long-term goals", "Reassess and compare outcomes with the set objectives"]'::jsonb, 3, 'Evaluation means reassessing the patient and comparing outcomes against the set goals.', 'Nursing Process'),
(3, 28, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'At which step of the nursing process is the PES statement written?', '["Implementation", "Planning", "Diagnosis", "Assessment"]'::jsonb, 2, 'The PES format (Problem, Etiology, Signs/Symptoms) is used to write the nursing diagnosis.', 'Nursing Process'),
(3, 29, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'Assessment of a client''s sensory abilities (vision, hearing), pain perception, memory, and decision-making ability is categorized under which Gordon pattern?', '["Coping-stress tolerance pattern", "Self-perception-self-concept pattern", "Cognitive-perceptual pattern", "Role-relationship pattern"]'::jsonb, 2, 'The cognitive-perceptual pattern covers sensory and neurological function, including vision, hearing, pain perception, and cognitive abilities such as memory and decision-making.', 'Nursing Process'),
(3, 30, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Nursing Process', 'While the nurse is providing a patient personal hygiene, she observes that his skin is excessively dry. During the procedure, he tells her that he is very thirsty. An appropriate nursing diagnosis would be:', '["Impaired skin integrity related to altered circulation", "Impaired skin integrity related to dehydration", "Potential for impaired skin integrity related to altered gland function", "Potential for impaired skin integrity related to dehydration"]'::jsonb, 3, 'Dry skin and thirst point to a fluid volume deficit (dehydration) as the underlying cause.', 'Nursing Process'),
(3, 31, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'The purchase of a new ventilator should be included in the:', '["Capital budget", "Salary budget", "Revenue budget", "Operating budget"]'::jsonb, 0, 'Major equipment purchases like a ventilator are capital expenditures, funded through the capital budget.', 'Management'),
(3, 32, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Which management tool helps identify a unit''s strengths, weaknesses, opportunities, and threats?', '["Fishbone diagram", "Flowchart", "Gantt chart", "SWOT analysis"]'::jsonb, 3, 'SWOT analysis identifies an organisation''s strengths, weaknesses, opportunities, and threats.', 'Management'),
(3, 33, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'The first step in an effective risk management cycle is typically to:', '["Identify the risk", "Implement a control plan immediately without analysis", "Report the incident to the media", "Terminate the staff member involved"]'::jsonb, 0, 'Risk management begins with identifying potential risks before they can be analysed, prioritised and controlled.', 'Management'),
(3, 34, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Which management level is responsible for policy formulation?', '["Middle managers", "First-line managers", "Top management", "Charge nurses"]'::jsonb, 2, 'Top management sets overall organisational policy and strategic direction.', 'Management'),
(3, 35, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'The BEST method for identifying the cause of repeated nursing errors is:', '["Root cause analysis", "Annual leave", "Staff transfer", "Guesswork"]'::jsonb, 0, 'Root cause analysis systematically identifies the underlying causes of recurring errors.', 'Management'),
(3, 36, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Which type of budget is most concerned with day-to-day hospital expenses?', '["Cash budget", "Capital budget", "Operating budget", "Master budget"]'::jsonb, 2, 'The operating budget covers routine, day-to-day operational expenses.', 'Management'),
(3, 37, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'The process of estimating the financial needs of a nursing unit is known as:', '["Auditing", "Budgeting", "Procurement", "Inventory"]'::jsonb, 1, 'Budgeting is the process of estimating and planning for a unit''s financial needs.', 'Management'),
(3, 38, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Which staffing pattern provides continuous nursing care by the same nurse throughout the patient''s hospital stay?', '["Functional nursing", "Case method", "Team nursing", "Primary nursing"]'::jsonb, 3, 'Primary nursing assigns one nurse to provide continuous, comprehensive care to a patient throughout their stay.', 'Management'),
(3, 39, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Discipline, as part of the Controlling function of management, should ideally be:', '["Used only as a first response before any coaching or feedback", "Avoided entirely regardless of the situation", "Applied inconsistently depending on personal relationships", "Fair, consistent, and applied according to established policy"]'::jsonb, 3, 'Effective disciplinary practice is fair, consistent and policy-based, typically following a progressive approach rather than being the very first response to an issue.', 'Management'),
(3, 40, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'In functional nursing, care is organized according to:', '["Family preference", "Patient diagnosis", "Nursing tasks", "Bed numbers"]'::jsonb, 2, 'Functional nursing organises care delivery around specific tasks rather than the whole patient.', 'Management'),
(3, 41, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Inventory management primarily aims to:', '["Increase hospital costs", "Eliminate documentation", "Reduce patient admissions", "Ensure availability of supplies"]'::jsonb, 3, 'Inventory management exists to ensure needed supplies are consistently available without excess waste.', 'Management'),
(3, 42, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'A manager who encourages staff to report errors without fear of unfair punishment is promoting a:', '["Competitive culture", "Punitive culture", "Blame culture", "Just culture"]'::jsonb, 3, 'A just culture encourages open error reporting by focusing on system factors rather than unfair individual blame.', 'Management'),
(3, 43, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'The ICU manager knows that some of her staffs prefers to be directed rather than to be allowed to use initiative or to exercise responsibility. This statement implies:', '["Theory y", "Theory b", "Theory x", "Theory A"]'::jsonb, 2, 'Preferring direction over independent initiative reflects Theory X assumptions about workers.', 'Management'),
(3, 44, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Which communication technique is MOST effective during patient handover?', '["Verbal report without documentation", "Text messages only", "Structured communication (e.g., SBAR)", "Informal conversation"]'::jsonb, 2, 'SBAR (Situation-Background-Assessment-Recommendation) is a structured communication technique proven effective for handovers.', 'Management'),
(3, 45, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'Management', 'Which document outlines the duties and responsibilities of a staff nurse?', '["Job description", "Duty roster", "Ward report", "Nursing care plan"]'::jsonb, 0, 'A job description formally outlines the duties, responsibilities, and expectations of a role.', 'Management'),
(3, 46, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A patient''s confidential information may be disclosed in which instance?', '["To pay the patient''s hospital bill", "To prevent harm or grievous injury", "To tell the doctor the truth", "In order to take him to the hospital"]'::jsonb, 1, 'Confidential information may be disclosed without consent when needed to prevent serious harm to the patient or others, or when required by law.', 'GSE 420 · Ethico-legal Aspects'),
(3, 47, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A patient with advanced cancer requests discontinuation of chemotherapy. The nurse supports this decision based on:', '["Justice", "Autonomy", "Nonmaleficence", "Beneficence"]'::jsonb, 1, 'Autonomy respects the patient''s right to self-determination.', 'GSE 420 · Ethico-legal Aspects'),
(3, 48, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Which ethical principle is demonstrated by respecting a competent patient''s informed refusal of treatment?', '["Justice", "Fidelity", "Beneficence", "Autonomy"]'::jsonb, 3, 'Respecting a competent patient''s informed refusal of treatment reflects the ethical principle of autonomy.', 'GSE 420 · Ethico-legal Aspects'),
(3, 49, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A nurse is asked by a patient''s employer for information about the patient''s diagnosis and prognosis. The nurse''s appropriate response is to:', '["Provide the requested information immediately, since the employer is asking on the patient''s behalf", "Share only positive information", "Decline to share any information without the patient''s explicit, documented consent, citing confidentiality obligations", "Share information only if the employer insists strongly"]'::jsonb, 2, 'Patient confidentiality obligations mean health information cannot be disclosed to third parties, including employers, without the patient''s explicit informed consent.', 'GSE 420 · Ethico-legal Aspects'),
(3, 50, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A patient’s family asks about autopsy after death. The nurse states:', '["\"Autopsy is unnecessary.\"", "\"Autopsy requires consent.\"", "\"Autopsy is only for forensic cases.\"", "\"Autopsy is mandatory.\""]'::jsonb, 1, 'Autopsy requires informed consent from next of kin.', 'GSE 420 · Ethico-legal Aspects'),
(3, 51, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The right to withdraw from a research study at any time is part of the subject''s right to:', '["Compensation", "Data ownership", "Anonymity only", "Self-determination"]'::jsonb, 3, 'Being free to change one''s mind and leave a study without penalty is a core aspect of a subject''s autonomy over their own participation.', 'GSE 420 · Ethico-legal Aspects'),
(3, 52, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A critically-ill patient has a "Living Will" in the chart. The patient''s condition has deteriorated, but the spouse wants "everything done" regardless of the patient''s wishes. Which ethical principle is the spouse violating?', '["Autonomy", "Non-maleficence", "Justice", "Beneficence"]'::jsonb, 0, 'Overriding a patient''s documented wishes (Living Will) disregards their autonomy.', 'GSE 420 · Ethico-legal Aspects'),
(3, 53, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A nurse is caring for a patient who is refusing treatment for his condition. The patient''s family is pressuring the nurse to persuade the patient to accept treatment. What should the nurse do?', '["Respect the patient''s autonomy and allow him refuse treatment.", "Persuade the patient to accept treatment to satisfy the family''s wishes", "Seek a court order to force the patient to accept treatment", "Consult with another nurse to determine the best course of action"]'::jsonb, 0, 'Respecting patient autonomy means allowing a competent patient to refuse treatment, even under family pressure.', 'GSE 420 · Ethico-legal Aspects'),
(3, 54, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Which four elements must all be proven for a nurse to be found legally negligent?', '["Duty of care, breach of duty, harm, and breach causing the harm", "Intent, motive, opportunity, and consequence", "Only that harm occurred, regardless of cause", "Consent, capacity, communication, and confidentiality"]'::jsonb, 0, 'Negligence requires proof of all four elements: a duty of care existed, that duty was breached, harm resulted, and the breach directly caused the harm.', 'GSE 420 · Ethico-legal Aspects'),
(3, 55, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Which principle is an obligation to tell the truth and not lie or deceive the patient?', '["Confidentiality", "Veracity", "Fidelity", "Justice"]'::jsonb, 1, 'Veracity is the duty to tell the truth. Fidelity means keeping promises.', 'GSE 420 · Ethico-legal Aspects'),
(3, 56, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', '''Veracity'' as an ethical principle in nursing means:', '["Avoiding harm", "Fairness in resource distribution", "Truthfulness and honesty with patients", "Loyalty and faithfulness to commitments"]'::jsonb, 2, 'Veracity is the ethical duty to be truthful and honest with patients about their condition and care.', 'GSE 420 · Ethico-legal Aspects'),
(3, 57, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A nurse experiences moral distress when a terminally ill patient receives aggressive CPR. This arises from:', '["Ethical dilemma", "Personal values conflict", "Inadequate staffing", "Legal obligation"]'::jsonb, 1, 'Moral distress occurs when actions conflict with personal ethics.', 'GSE 420 · Ethico-legal Aspects'),
(3, 58, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', '''Non-maleficence'' as an ethical principle means:', '["Being fair and just to all patients", "Doing no harm to the patient", "Doing good for the patient", "Being honest with the patient"]'::jsonb, 1, 'Non-maleficence is the principle of ''first, do no harm'' — avoiding actions that could injure the patient.', 'GSE 420 · Ethico-legal Aspects'),
(3, 59, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The physician instructed the Nurse in the ICU to run a slow code as the family was not agreed for DNR. The approach used here to help the patient and family in the end of life is termed as:', '["Spiritual support", "Ethical Dilemma", "DNR", "Life Support"]'::jsonb, 1, 'Performing a deliberately less-aggressive code due to family/DNR disagreement is a classic ethical dilemma in critical care.', 'GSE 420 · Ethico-legal Aspects'),
(3, 60, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A nurse notices a suspicious lesion on a neonate but, knowing it could worsen, does not report it, and the baby is sent home and deteriorates. This is:', '["Inadvertent negligence", "Advertent negligence", "Assault", "Battery"]'::jsonb, 1, 'Advertent negligence: the carer knows the likely harmful consequence of omitting a required action and omits it anyway, e.g. noticing a lesion and not acting.', 'GSE 420 · Ethico-legal Aspects'),
(3, 61, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Marketing mix (4Ps) includes product, price, place and:', '["People only", "Promotion", "Profit", "Planning"]'::jsonb, 1, 'Services often add people, process and physical evidence.', 'GST 408 · Entrepreneurship'),
(3, 62, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Market segmentation means:', '["Selling to everyone the same way", "Closing the business", "Dividing customers into groups with similar needs", "Reducing prices only"]'::jsonb, 2, 'It helps target services.', 'GST 408 · Entrepreneurship'),
(3, 63, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Cash flow problems in a business occur when:', '["All customers pay in advance", "Profit is very high", "The business has no costs", "Money coming in is less than money going out at a given time"]'::jsonb, 3, 'Even profitable businesses can fail from poor cash flow.', 'GST 408 · Entrepreneurship'),
(3, 64, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A limited liability company means the owners:', '["Are liable only up to the amount they invested", "Cannot make profits", "Pay no taxes", "Are liable for all debts personally"]'::jsonb, 0, 'It is a separate legal entity.', 'GST 408 · Entrepreneurship'),
(3, 65, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Value Added Tax (VAT) is a tax on:', '["Land only", "Imports only", "Personal income only", "The sale of goods and services"]'::jsonb, 3, 'Businesses collect it on behalf of the government.', 'GST 408 · Entrepreneurship'),
(3, 66, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Customer satisfaction in a health business is important because it:', '["Has no effect on income", "Reduces quality", "Encourages repeat use and referrals", "Increases costs only"]'::jsonb, 2, 'Feedback helps improve services.', 'GST 408 · Entrepreneurship'),
(3, 67, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'An entrepreneur is a person who:', '["Identifies an opportunity and takes risks to start a business", "Only buys shares", "Avoids all risk", "Only works for a salary"]'::jsonb, 0, 'Entrepreneurs combine resources to create value.', 'GST 408 · Entrepreneurship'),
(3, 68, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A franchise is a business arrangement in which:', '["A person pays to use an established brand and system", "The government owns all shares", "There is no brand", "Profits go only to charity"]'::jsonb, 0, 'The franchisor gives support and rules.', 'GST 408 · Entrepreneurship'),
(3, 69, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A variable cost changes with:', '["The owner''s mood", "The level of output or sales", "Time only", "Nothing"]'::jsonb, 1, 'Examples are supplies used per patient.', 'GST 408 · Entrepreneurship'),
(3, 70, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A SWOT analysis for a new private clinic assesses:', '["Supply, Wealth, Output and Trade", "Staff, Work, Office and Time", "Sales, Wages, Orders and Taxes", "Strengths, Weaknesses, Opportunities and Threats"]'::jsonb, 3, 'It helps plan strategy.', 'GST 408 · Entrepreneurship'),
(3, 71, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Which one is application software?', '["Microsoft Word", "Avast Antivirus", "Windows XP", "Android 11"]'::jsonb, 0, 'Microsoft Word is application software. Windows and Android are operating systems; antivirus is utility software.', 'GST 405 · Computer Studies'),
(3, 72, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'During electronic health documentation, which computer part allows a critical care nurse to enter patient data?', '["Operating system", "Output device", "Software", "Input device"]'::jsonb, 3, 'Input devices (keyboard, mouse, touchscreen, scanner) put data into the computer. Output devices (monitor, printer) display it.', 'GST 405 · Computer Studies'),
(3, 73, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Which of the following units of data is the largest?', '["Terabyte (TB)", "Gigabyte (GB)", "Kilobyte (KB)", "Megabyte (MB)"]'::jsonb, 0, 'A Terabyte is the largest unit listed, equal to about one trillion bytes. The order from smallest to largest is: Kilobyte (about one thousand bytes), Megabyte (about one million bytes), Gigabyte (about one billion bytes), and Terabyte.', 'GST 405 · Computer Studies'),
(3, 74, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Random Access Memory (RAM) differs from Read Only Memory (ROM) in that RAM is:', '["Not involved in program execution", "Used only for long-term archival storage", "Volatile — its contents are lost when power is off", "Permanent and non-volatile"]'::jsonb, 2, 'RAM is volatile working memory used for actively running programs and data; its contents are lost when the computer powers off, unlike ROM.', 'GST 405 · Computer Studies'),
(3, 75, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Batch processing, as a method of file processing, is best described as:', '["A method used only for video files", "Collecting and processing a group of transactions together at a scheduled time", "Processing transactions immediately as they occur, one at a time", "Processing that requires no computer at all"]'::jsonb, 1, 'Batch processing accumulates data over a period and processes it together at a set time, rather than immediately as each transaction occurs.', 'GST 405 · Computer Studies'),
(3, 76, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Which of the following computer components is known as the "brain" of the computer, responsible for executing instructions?', '["Hard Drive", "ROM (Read-Only Memory)", "CPU (Central Processing Unit)", "RAM (Random Access Memory)"]'::jsonb, 2, 'The CPU is the central processing unit, which is the electronic circuitry that executes instructions and performs the basic arithmetic, logical, control, and input/output (I/O) operations specified by computer programs.', 'GST 405 · Computer Studies'),
(3, 77, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'A nurse is explaining the units of data to a patient. The smallest unit of data in a computer is a:', '["Bit", "Byte", "Kilobyte", "Megabyte"]'::jsonb, 0, 'A bit (binary digit) is the most basic unit of information in computing and is a one or a zero. A byte is a group of 8 bits. The other options are larger units of data.', 'GST 405 · Computer Studies'),
(3, 78, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Which one is NOT an input device?', '["Mouse", "Scanner", "Monitor", "Keyboard"]'::jsonb, 2, 'A monitor is an output device. Mouse, keyboard and scanner are input devices.', 'GST 405 · Computer Studies'),
(3, 79, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Index-sequential file organisation allows records to be accessed:', '["Never — it is a theoretical method with no real use", "Only in the exact order they were originally entered, with no shortcuts", "Both sequentially and directly via an index, combining the benefits of both methods", "Only by physically searching every record one by one with no index"]'::jsonb, 2, 'Index-sequential organisation maintains an index that allows direct access to specific records while still supporting sequential processing.', 'GST 405 · Computer Studies'),
(3, 80, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 405 · Computer Studies', 'In data transfer process, what does FTP stand for?', '["File transfer protection", "File transfer program", "File transfer Protocol", "File transmission protocol"]'::jsonb, 2, 'FTP is File Transfer Protocol, a standard way of moving files between computers over a network.', 'GST 405 · Computer Studies'),
(3, 81, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Displacement means:', '["Making excuses for behaviour", "Redirecting feelings onto a safer target", "Blocking memories completely", "Behaving the opposite of one''s feelings"]'::jsonb, 1, 'E.g. shouting at the nurse after bad news from the doctor.', 'GST 401 · Behavioural Science'),
(3, 82, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'One of the following is called the positive stress.', '["Worries", "Anxiety", "Happiness", "Eustress"]'::jsonb, 3, 'Eustress is the recognised term for positive, beneficial stress.', 'GST 401 · Behavioural Science'),
(3, 83, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A client has multiple identified nursing diagnoses. Which method is commonly used to prioritize these diagnoses?', '["Alphabetical order of the diagnostic labels", "The order in which they were identified during assessment", "Client''s personal preference alone, without clinical judgment", "Maslow''s Hierarchy of Needs, addressing physiological and safety needs first"]'::jsonb, 3, 'Maslow''s Hierarchy of Needs is a common framework for prioritizing nursing diagnoses, with physiological and safety needs typically addressed first.', 'GST 401 · Behavioural Science'),
(3, 84, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A patient is admitted to the ICU following a suicide attempt by drug overdose. Once medically stabilised, the nurse''s priority alongside physical care is to:', '["Discharge the patient as soon as vital signs normalise, with no further assessment", "Avoid discussing the event with the patient entirely", "Assess psychiatric risk, ensure a safe environment, and involve mental health/psychiatric services", "Focus exclusively on physical recovery with no psychological assessment"]'::jsonb, 2, 'Care after a suicide attempt must include psychiatric risk assessment, ensuring a safe environment (e.g. removing means of harm), and timely involvement of mental health services, alongside physical stabilisation.', 'GST 401 · Behavioural Science'),
(3, 85, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Rationalisation is:', '["Giving logical-sounding excuses for unacceptable behaviour", "Acting like a child", "Forgetting a painful event", "Refusing to believe a diagnosis"]'::jsonb, 0, 'It protects self-esteem.', 'GST 401 · Behavioural Science'),
(3, 86, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A client who has managed a chronic illness for many years tells the nurse, ''I''ve learned so much about myself through this journey, and I feel I''ve grown into the best version of myself.'' This statement best reflects which level of Maslow''s hierarchy?', '["Self-esteem needs", "Physiological needs", "Safety and security needs", "Self-actualization needs"]'::jsonb, 3, 'Self-actualization, the highest level in Maslow''s hierarchy, involves realizing one''s fullest potential, personal growth, and self-fulfillment — reflected in this client''s sense of personal growth through adversity.', 'GST 401 · Behavioural Science'),
(3, 87, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A client who is newly diagnosed with a colostomy expresses distress, saying, ''I don''t feel like myself anymore; I feel disfigured.'' This response falls primarily within which of Roy''s adaptive modes?', '["Interdependence mode", "Physiological-physical mode", "Self-concept/group identity mode", "Role function mode"]'::jsonb, 2, 'Concerns about body image and personal identity following a change such as a colostomy fall within the self-concept/group identity mode, which addresses the person''s beliefs and feelings about the self, including body image.', 'GST 401 · Behavioural Science'),
(3, 88, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A hospitalized client repeatedly asks the nurse to keep the bed rails up and the call light within reach, expressing fear of falling. This behavior is best explained by which level of Maslow''s hierarchy?', '["Safety and security needs", "Physiological needs", "Love and belonging needs", "Self-actualization needs"]'::jsonb, 0, 'Concerns about physical safety and protection from harm, such as fear of falling, correspond to the safety and security level of Maslow''s hierarchy, which follows physiological needs.', 'GST 401 · Behavioural Science'),
(3, 89, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Health belief model suggests that people take health action when they:', '["Have no symptoms or risk", "Believe they are at risk and the benefits outweigh the barriers", "Are told to without explanation", "Have no knowledge of the illness"]'::jsonb, 1, 'It helps plan patient education.', 'GST 401 · Behavioural Science'),
(3, 90, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Abraham Maslow''s hierarchy of needs is typically depicted as a pyramid with which level at the very base, representing the most fundamental needs?', '["Self-actualization needs", "Physiological needs", "Love and belonging needs", "Safety and security needs"]'::jsonb, 1, 'Physiological needs, such as oxygen, food, water, and elimination, form the base of Maslow''s pyramid because they must generally be met first to sustain life before higher-level needs can be addressed.', 'GST 401 · Behavioural Science'),
(3, 91, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'In report writing, the passive voice sentence is:', '["The nurse is dressing the wound.", "The wound was dressed by the nurse.", "The nurse dressed the wound.", "Dress the wound, nurse."]'::jsonb, 1, 'Passive voice focuses on the action, not the person.', 'GST 400 · Use of English'),
(3, 92, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the word closest in meaning to ''contraindication'':', '["A reason not to use a treatment", "A side effect", "A type of drug", "A reason to use a treatment"]'::jsonb, 0, 'An indication is a reason to use it.', 'GST 400 · Use of English'),
(3, 93, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the word closest in meaning to ''ambulate'':', '["Eat", "Breathe", "Sleep", "Walk"]'::jsonb, 3, 'Early ambulation reduces DVT risk.', 'GST 400 · Use of English'),
(3, 94, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'The abbreviation ''NPO'' in a medical order means:', '["No pain observed", "Normal post-operative", "Nurse patient order", "Nothing by mouth"]'::jsonb, 3, 'From Latin ''nil per os''.', 'GST 400 · Use of English'),
(3, 95, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correct sentence:', '["The data was analysed by the team.", "The data were analysed by the team.", "The datas were analysed by the team.", "The data is been analysed by the team."]'::jsonb, 1, 'In formal writing ''data'' is often treated as plural.', 'GST 400 · Use of English'),
(3, 96, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'The plural of ''bacterium'' is:', '["Bacteria", "Bacterie", "Bacterias", "Bacteriums"]'::jsonb, 0, 'Similar: datum/data, medium/media.', 'GST 400 · Use of English'),
(3, 97, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correctly spelt word:', '["Hemmorrhage", "Haemorrage", "Haemorrhage", "Haemorhage"]'::jsonb, 2, 'From Greek haima (blood) and rhegnynai (to burst).', 'GST 400 · Use of English'),
(3, 98, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correct form: ''Each of the nurses ___ responsible for the count.''', '["is", "were", "are", "be"]'::jsonb, 0, '''Each'' takes a singular verb.', 'GST 400 · Use of English'),
(3, 99, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'The plural of ''diagnosis'' is:', '["Diagnosi", "Diagnosises", "Diagnosis", "Diagnoses"]'::jsonb, 3, 'Words ending in -sis change to -ses.', 'GST 400 · Use of English'),
(3, 100, 'Perioperative Mock — Day 4 Night (Nov 2026)', 'GST 400 · Use of English', 'The suffix ''-ostomy'' means:', '["Surgical removal", "Inflammation", "Making a surgical opening (stoma)", "Pain"]'::jsonb, 2, 'E.g. colostomy, tracheostomy.', 'GST 400 · Use of English');
